import React from 'react';
import styled from 'styled-components';

const HomeContainer = styled.div`
  padding: 20px;
  text-align: center;
`;

const Home = () => {
  return (
    <HomeContainer>
      <h1>Welcome to My Portfolio</h1>
      <p>I’m Zahid Hussain, a passionate chef with over 8 years of experience, with a keen eye for taste, texture, and presentation. This portfolio showcases my journey, work experience, and skills that I have honed over the years. Feel free to explore my work, check out my Gallery, and get to know more about what I do. If you have any questions don’t hesitate to reach out! Thank you!!
      </p>
    </HomeContainer>
  );
};

export default Home;
